class NullsLastOrderingFilter(filters.OrderingFilter):
    def filter_queryset(self, request, queryset, view):
        ordering = self.get_ordering(request, queryset, view)
        if not ordering:
            return queryset

        fields = []
        for field in ordering:
            if field.startswith("-"):
                fields.append(F(field[1:]).desc(nulls_last=True))
            else:
                fields.append(F(field).asc(nulls_last=True))
        return queryset.order_by(*fields)

class BookViewSet(viewsets.ModelViewSet):
    queryset = Book.objects.all()
    serializer_class = BookSerializer
    filter_backends = [filters.OrderingFilter]
    ordering_fields = ["price", "published_at"]
    ordering = ["-published_at"]

    def filter_queryset(self, queryset):
        queryset = super().filter_queryset(queryset)
        reverse = self.request.query_params.get("reverse")
        if reverse and reverse.lower() in ("true", "1"):
            current = self.request.query_params.get("ordering")
            if current and current.startswith("-"):
                queryset = queryset.order_by(current[1:])
            elif current:
                queryset = queryset.order_by("-" + current)
        return queryset

